/* Static, deterministic design data. No network requests or product services. */
const I=(name,extra='')=>`<i class="symbol ${extra}" style="--symbol:url('${SYMBOL_DATA[name]||SYMBOL_DATA['circle']}')" aria-hidden="true"></i>`;
const pill=(text,type='',icon='')=>`<span class="pill ${type}">${icon?I(icon):''}${text}</span>`;
const button=(text,type='primary',icon='',target='')=>`<button type="button" class="btn ${type}" ${target?`data-jump="${target}"`:''}>${icon?I(icon):''}${text}</button>`;
const notice=(text,type='',icon='info.circle')=>`<div class="notice ${type}">${I(icon)}<div>${text}</div></div>`;
const row=(a,b,cls='')=>`<div class="row ${cls}">${a}${b}</div>`;
const divider='<div class="divider"></div>';
const footer=(text='演示数据')=>`<div class="demo-tag">${text}</div><div class="home-indicator"></div>`;
const tabs=(active='行程')=>`<div class="bottom-tabs">${[['house','行程','home'],['tram.fill','列车','search'],['gearshape','设置','settings']].map(([icon,label,target])=>`<button class="tab-item ${label===active?'active':''}" data-jump="${target}">${I(label==='行程'&&active===label?'house.fill':icon)}${label}</button>`).join('')}</div>`;
function status(time='17:24',ipad=false){return `<div class="statusbar"><span>${ipad?'11月6日 周五　':''}${time}</span>${!ipad?'<div class="island-hardware"></div>':''}<span class="status-icons">${I('antenna.radiowaves.left.and.right')}${I('wifi')}${I('battery.100')}</span></div>`}
function nav(title='',back='',right='ellipsis',target='home'){return `<div class="nav-bar">${back?`<button class="nav-back" data-jump="${target}">${I('chevron.left')}${back}</button>`:'<span style="width:44px"></span>'}<span class="nav-title">${title}</span>${right?`<button class="icon-button" aria-label="${right==='plus'?'添加行程':'更多选项'}" data-jump="${right==='plus'?'search':'edit'}">${I(right)}</button>`:'<span style="width:44px"></span>'}</div>`}
function phone(id,body,{time='17:24',title='',back='',right='ellipsis',tab=false,dark=false,cls='',width=402,height=874,modal='',backTarget='home'}={}){return{id,type:'phone',width,height,html:`<article class="art phone ${dark?'dark':''} ${!tab?'no-tabs':''} ${cls}" id="art-${id}" aria-label="${id}">${status(time)}${nav(title,back,right,backTarget)}<div class="screen-body">${body}</div>${tab?tabs(typeof tab==='string'?tab:'行程'):''}${footer()}${modal}</article>`}}
function hero({stage='行进中',label='距 Ottawa 预计到达',count='1:18:00',foot='预计 18:42 到达',detail='晚点 12 分钟',progress=72,plan='计划 18:30',unit='',faint=false}={}){return `<div class="hero ${faint?'faint':''}">${row(pill(stage,'','tram.fill'),'<span class="tiny muted">VIA 44 · 第 1 段</span>')}<div class="hero-label" style="margin-top:20px">${label}</div><div class="count mono">${count}${unit?`<span class="unit">${unit}</span>`:''}</div>${row(`<span class="small ${detail.includes('晚点')?'amber':'muted'}">${detail}</span>`,`<span class="small muted">${plan}</span>`)}${progress!==null?`<div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><div class="progress-label"><span>Toronto</span><span>Ottawa</span></div>`:''}<div class="hero-footer"><span>${foot}</span>${I('arrow.up.right','sm')}</div></div>`}
const stops=[['Toronto','14:00','已发车 · 数据已确认','14:00','done'],['Kingston','16:28','已到站 · 数据已确认','16:20','done'],['Smiths Falls','17:38','下一站 · 预计到达','17:30','current'],['Ottawa','18:42','目的站 · 预计到达','18:30','']];
function timeline(items=stops,compact=false){return `<div class="timeline ${compact?'compact-timeline':''}">${items.map(([name,time,desc,old,state])=>`<div class="stop ${state||''}"><div class="rail"><span class="dot"></span></div><div><div class="station-name">${name}</div><div class="station-desc">${desc}</div></div><div class="stop-time ${state==='current'?'accent':''}">${time}${old&&old!==time?`<span class="old">${old}</span>`:''}</div></div>`).join('')}</div>`}
function routeCard({transfer=false,compact=false,complete=false,future=false,planned=false}={}){return `<div class="card ${compact?'compact':''}">${row(`<span class="train-mark">${I('tram.fill','sm')} VIA 44${transfer?' + VIA 38':''}</span>`,pill(complete?'已完成':future?'参考时刻':'11月6日',future?'amber':'neutral'))}<div class="route-title" style="margin:14px 0 18px">Toronto ${I('arrow.right')} ${transfer?'Montréal':'Ottawa'}</div><div class="journey-line"><div class="track"></div><div class="journey-stops"><div class="station-row"><span class="name">Toronto</span><span class="time mono">14:00</span></div><div class="station-row"><span class="name">${transfer?'Montréal':'Ottawa'}</span><div class="col" style="align-items:flex-end"><span class="time mono">${transfer?'21:12':future||planned?'18:30':'18:42'}</span>${!future&&!planned&&!transfer?'<span class="small amber">计划 18:30 · 晚点 12 分钟</span>':''}</div></div></div></div>${transfer?'<div class="transfer-strip" style="margin-top:18px"><span>Ottawa 换乘 · 2 段列车</span><span>计划间隔 45 分钟</span></div>':''}</div>`}
function mapArt(tall=false,city='Ottawa'){return `<div class="map-art" ${tall?'style="height:270px"':''} aria-label="列车位置示意，非真实地图"><svg viewBox="0 0 500 220" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Ottawa 附近的地图示意"><rect width="500" height="220" fill="#e9ecde"/><path d="M0 140 Q75 106 125 137 T255 136 T380 82 T500 100 L500 220 L0 220Z" fill="#d1e1dc"/><path d="M-30 35 Q90 70 188 44 T415 56 T550 18" fill="none" stroke="#d0d7c7" stroke-width="18"/><path d="M-30 35 Q90 70 188 44 T415 56 T550 18" fill="none" stroke="#f8f8ed" stroke-width="13"/><path d="M50 -10L120 100L230 110L310 60L420 55L500 25M290 0L310 60L350 130L440 150M15 90L110 86L180 9M200 220L230 110L210 0" fill="none" stroke="#faf9ef" stroke-width="5"/><path d="M90 0L130 70M30 70L70 85M335 0L365 45M380 120L405 220" stroke="#d7dec9" stroke-width="2"/><text x="315" y="40" font-family="-apple-system,sans-serif" font-size="13" fill="#5d705a">${city}</text><text x="70" y="115" font-family="-apple-system,sans-serif" font-size="11" fill="#5d705a">${city==='Toronto'?'Union Station':'Smiths Falls'}</text><text x="298" y="182" font-family="-apple-system,sans-serif" font-size="11" fill="#72928a" transform="rotate(-12 298 182)">${city==='Toronto'?'Lake Ontario':'Rideau River'}</text><circle cx="211" cy="98" r="18" fill="#FFCC00" opacity=".12"/><circle cx="211" cy="98" r="8" fill="#FFCC00" stroke="#fffefa" stroke-width="3"/><circle cx="336" cy="57" r="4" fill="#fffefa" stroke="#FFCC00" stroke-width="2"/></svg><div class="map-top">${I('location.fill')}位置示意 · 演示</div><div class="map-expand">${I('arrow.up.right')}</div></div>`}
const nextSegment=(detailed=false)=>`<div class="card compact">${row(`<span class="train-mark">${I('arrow.triangle.branch','sm')}下一段 · VIA 38</span>`,`<span class="small muted">19:15 发车</span>`)}<div class="row" style="margin-top:11px"><span style="font-size:14px">Ottawa ${I('arrow.right','sm')} Montréal</span><span class="small">21:12 到达</span></div>${detailed?'<div class="transfer-strip" style="margin-top:13px"><span>预计到达后，距下一段计划发车</span><b>33 分钟</b></div>':''}</div>`;
const section=(title,content,right='')=>`<section><div class="section-label"><span>${title}</span><span class="muted">${right}</span></div>${content}</section>`;
const steps=n=>`<div class="step-indicator">${[1,2,3].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>`;
function formTitle(title,sub,n=1){return `${row(`<span class="tiny muted">添加行程 · ${n}/3</span>`,steps(n))}<h1>${title}</h1><div class="form-subtitle">${sub}</div>`}
function field(label,value,icon='chevron.right'){return `<div class="field"><span class="muted">${label}</span><span class="row"><span class="value mono">${value}</span>${icon?I(icon,'sm'):''}</span></div>`}
function listRow(label,value='',icon='',target=''){return `<div class="list-row" ${target?`data-jump="${target}" role="button" tabindex="0"`:''}>${icon?I(icon):''}<div class="col"><span>${label}</span></div><span class="muted small">${value}</span>${I('chevron.right','chev')}</div>`}
const dateLabel='<span class="small muted">11月6日 周五</span>';
const screens={};
function add(screen,label,desc=''){screens[screen.id]={...screen,label,desc};}

/* Main journey pages */
add(phone('home',`${row('<div><div class="small muted" style="margin-bottom:5px">11月6日，星期五</div><h1>我的行程</h1></div>',`<button class="icon-button" data-jump="search" aria-label="添加行程">${I('plus')}</button>`)}<div class="row"><span class="small weight">当前行程</span>${pill('主行程','','location.fill')}</div><div class="card tint">${row('<span class="train-mark">VIA 44 + VIA 38</span>',pill('行进中'))}<div class="route-title" style="font-size:27px;margin-top:19px">Toronto<br><span class="muted" style="font-weight:400">经 Ottawa</span> ${I('arrow.right')} Montréal</div><div class="divider" style="margin:19px 0;background:color-mix(in srgb,var(--accent) 15%,transparent)"></div><div class="small accent">距 Ottawa 预计到达</div><div style="font-size:53px;letter-spacing:-2.5px;font-weight:400;line-height:1.25" class="mono">1 小时 18 分</div>${row('<span class="small amber">预计 18:42 · 晚点 12 分钟</span>',I('chevron.right','sm'))}<div class="transfer-strip" style="background:var(--surface);margin-top:19px"><span>下一段 VIA 38 · 19:15 发车</span><b>间隔 33 分钟</b></div></div>${section('接下来的行程',`<div class="card compact">${row('<span class="train-mark">VIA 61</span>',pill('待同步','amber'))}<div style="font-size:18px;font-weight:550;margin:12px 0 7px">Montréal ${I('arrow.right','sm')} Toronto</div>${row('<span class="small muted">11月8日 · 06:45</span>','<button class="edit-link" data-jump="reference">查看行程</button>')}</div>`)}<div class="spacer"></div><div class="tiny muted">默认突出最近的未完成行程 · 可切换主行程</div>`,{tab:true,right:'',title:''}),'我的行程 · 进行中');
add(phone('empty',`<h1>我的行程</h1><div class="spacer"></div><div class="empty-graphic">${I('tram.fill')}</div><div class="empty-copy"><h2>还没有行程</h2><p>添加列车，查看出门、乘车和换乘时间。<br>支持离线查看最近的数据。</p></div><div style="margin-top:10px">${button('添加第一趟行程','primary','plus','search')}</div><div class="spacer"></div><div class="notice neutral">${I('info.circle')}<div>无需账号。行程保存在这台设备上，断网时也能查看最近的信息。</div></div>`,{tab:true,time:'12:55',right:''}),'首次使用 · 空状态');
add(phone('upcoming',`${row('<h1>我的行程</h1>',`<button class="icon-button" data-jump="search" aria-label="添加行程">${I('plus')}</button>`)}<div class="small muted">11月6日 周五 · 待出发</div>${hero({stage:'出发前',label:'距计划出门',count:'35:00',foot:'13:30 出门 · 前往车站 30 分钟',detail:'火车计划 14:00 发车',plan:'',progress:null})}${routeCard({transfer:true,compact:true})}<div class="spacer"></div>${button('查看完整行程','primary','','before')}<div class="tiny muted" style="text-align:center">实时活动已开启</div>`,{tab:true,right:'',time:'12:55'}),'我的行程 · 待出发');
function detail(id,{transfer=false,dark=false,offline=false,large=false,small=false}={}){let h=hero();let middle=section('沿途站点',timeline(stops,transfer||small), '计划 / 预计');if(transfer)middle=section('当前段 · Toronto → Ottawa',timeline(stops.slice(1),true),'VIA 44');if(large||offline)middle=section('下一站',`<div class="card">${row('<div class="col"><span class="station-name">Smiths Falls</span><span class="small muted">计划 17:30</span></div>','<span class="final-time mono">17:38</span>')}</div>`);return phone(id,`${row(`<div class="col"><h2>${transfer?'前往 Montréal':'前往 Ottawa'}</h2><span class="small muted">11月6日 周五${transfer?' · 2 段列车':''}</span></div>`,pill(offline?'离线':'实时',offline?'neutral':'','antenna.radiowaves.left.and.right'))}${offline?notice('设备已断网 · 最近更新 17:12<br>以下时间基于 12 分钟前的数据。','neutral','wifi.slash'):''}${h}${middle}${transfer?nextSegment(true):large||small?'':mapArt()}${!small&&!transfer&&!large?`<div class="tiny muted">${offline?'最近获取 17:12 · 定位上报 17:11':'17:24 获取 · 定位上报 17:23'} · 进度按时刻推算</div>`:''}${large?'<div class="spacer"></div>'+button('已上车 · 更正状态','outline','checkmark'):small?'<div class="tiny muted">17:24 更新 · 进度按时刻推算</div>':transfer?'<div class="tiny muted">17:24 更新 · 进度按时刻推算</div>':''}`,{title:'行程详情',back:'行程',dark,tab:!large&&!small,cls:`detail-screen ${large?'large-type':small?'small-phone':''}`,width:small?320:402,height:small?740:874})}
add(detail('detail'),'单程 · 行进中');add(detail('connection',{transfer:true}),'换乘行程 · 第一段');add(detail('detail-dark',{dark:true}),'单程 · 深色模式');

/* Creation flow */
const option=(num,from,to,dep,arr,selected=false,sub='11月6日 周五')=>`<div class="train-option">${row(`<span class="train-mark">${I('tram.fill','sm')}VIA ${num}</span>`,`<span class="selection-circle ${selected?'selected':''}">${selected?I('checkmark'):''}</span>`)}<div class="route-title">${from} ${I('arrow.right')} ${to}</div>${row(`<span class="mono" style="font-size:20px">${dep} <span class="muted" style="font-size:13px;margin:0 5px">—</span> ${arr}</span>`,`<span class="tiny muted">${sub}</span>`)}</div>`;
add(phone('search',`${formTitle('选择列车','按车次号或车站搜索，选择出发日期。')}<div class="search">${I('magnifyingglass')}搜索车次或车站</div><div class="field"><span class="row">${I('calendar','sm')} 出发日期</span><span class="row"><span>11月6日 周五</span>${I('chevron.right','sm')}</span></div><div class="segmented"><span class="selected">全部班次</span><span>尚未发车</span></div>${option('44','Toronto','Ottawa','14:00','18:30',true)}${option('38','Ottawa','Montréal','19:15','21:12')}<div class="spacer"></div><div class="tiny muted">列表显示接口提供的班次，包含跨日长途列车。</div>${button('下一步','primary','','stations')}`,{title:'添加行程',back:'取消',right:'',time:'12:55'}),'01 · 选择车次');
const calendar=()=>`<div class="calendar">${row('<b>2026年11月</b>',`<span class="row accent">${I('chevron.left','sm')}${I('chevron.right','sm')}</span>`)}<div class="calendar-grid">${['日','一','二','三','四','五','六'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:30},(_,n)=>`<span class="${n===6?'selected':''}">${n+1}</span>`).join('')}${[1,2,3,4,5].map(n=>`<span class="other">${n}</span>`).join('')}</div></div>`;
add(phone('date',`${formTitle('选择出发日期','日期指本段上车站的当地出发日期。')}<div class="card compact">${row('<span class="train-mark">VIA 44</span>','<span class="small muted">Toronto → Ottawa</span>')}</div>${calendar()}${notice('11月7日尚无对应班次数据。将借用最近一班的计划时刻，实际日期的数据出现后再核对。','warning')}<div class="spacer"></div>${button('使用参考时刻继续','primary','','reference')}`,{title:'出发日期',back:'返回',right:'',time:'12:55',backTarget:'search'}),'02 · 未来日期');
const stepper=(value='30')=>`<div class="stepper"><button class="step-btn" aria-label="减少15分钟">${I('minus')}</button><div><div class="step-value mono">${value}</div><div class="step-unit">分钟</div></div><button class="step-btn" aria-label="增加15分钟">${I('plus')}</button></div>`;

/* Transfer planning */
add(phone('add-transfer',`${formTitle('选择换乘列车','仅显示在上一段下车站上车的列车。',3)}<div class="transfer-strip"><span>上一段到达 Ottawa</span><b class="mono">18:30 计划</b></div><div class="search">${I('magnifyingglass')}38</div>${field('出发日期','11月6日 周五','calendar')}${option('38','Ottawa','Montréal','19:15','21:12',true)}<div class="card compact">${row(`<span class="row">${I('arrow.triangle.branch','sm')}同站换乘</span>`,'<b class="small">45 分钟</b>')}<div class="small muted" style="margin-top:8px">上一段计划到达 18:30 → 下一段计划发车 19:15</div></div><div class="spacer"></div>${button('添加这一段','primary','','transfer-review')}`,{title:'添加换乘',back:'返回',right:'',time:'12:55',backTarget:'review'}),'07 · 添加下一段');
const leg=(num,from,to,dep,arr,tag='计划')=>`<div class="card compact">${row(`<span class="train-mark">${I('tram.fill','sm')}VIA ${num}</span>`,`<span class="tiny muted">${tag}</span>`)}<div style="margin-top:12px">${row(`<span>${from}</span>`,`<span class="mono">${dep}</span>`)}${row(`<span>${to}</span>`,`<span class="mono">${arr}</span>`)}</div></div>`;
add(phone('transfer-review',`${formTitle('确认换乘行程','Toronto → Ottawa → Montréal',3)}${leg('44','Toronto','Ottawa','14:00','18:30')}<div class="transfer-strip"><span>${I('arrow.triangle.branch','sm')} Ottawa · 同站换乘</span><b>间隔 45 分钟</b></div>${leg('38','Ottawa','Montréal','19:15','21:12')}${field('计划出门','13:30','')}${button('继续添加下一段','ghost','plus','add-transfer')}<div class="spacer"></div>${button('开启整趟行程的实时活动','primary','','connection')}<div class="tiny muted" style="text-align:center">一个实时活动，随当前车段切换</div>`,{title:'确认换乘行程',back:'返回',right:'',time:'12:55',backTarget:'add-transfer'}),'09 · 换乘行程确认');

/* Phases */
const phaseProgress=(current)=>`<div class="mini-steps">${['出发前','前往中','候车中','行进中'].map((s,n)=>`${n?'<i></i>':''}<span class="${s===current?'current':''}">${s}</span>`).join('')}</div>`;
add(phone('before',`${phaseProgress('出发前')}<h2>前往 Ottawa</h2>${hero({stage:'出发前',label:'距计划出门',count:'35:00',foot:'13:30 出门',detail:'前往车站需要 30 分钟',plan:'',progress:null})}${section('乘车信息',`<div class="list-group">${listRow('上车站','Toronto','location')}${listRow('火车计划发车','14:00','tram.fill')}${listRow('前往耗时','30 分钟','figure.walk','travel')}</div>`)}${notice('计划出门按你的设置计算。即使列车预计晚点，也不会自动推迟出门提醒。')}<div class="spacer"></div>${button('我已出门','primary','figure.walk','onway')}<div class="tiny muted" style="text-align:center">也会按设定时间自动进入前往阶段</div>`,{title:'行程详情',back:'行程',time:'12:55'}),'10 · 出发前');
add(phone('onway',`${phaseProgress('前往中')}<h2>前往 Toronto 车站</h2>${hero({stage:'前往中',label:'距火车计划发车',count:'18:00',foot:'计划 14:00 发车',detail:'预计 14:08 发车',plan:'晚点 8 分钟',progress:null})}${mapArt(false,'Toronto')}<div class="card compact"><div class="next-row">${I('location.fill')}<div class="col"><span class="weight">Toronto</span><span class="small muted">你的上车站 · VIA 44</span></div><span class="small accent">计划 14:00</span></div></div><div class="spacer"></div>${button('我已到站','primary','checkmark','waiting')}<div class="tiny muted" style="text-align:center">计划发车前 15 分钟自动进入候车阶段</div>`,{title:'行程详情',back:'行程',time:'13:42'}),'11 · 前往中');
add(phone('waiting',`${phaseProgress('候车中')}<h2>在 Toronto 候车</h2>${hero({stage:'候车中',label:'距列车预计发车',count:'13:00',foot:'预计 14:08 发车',detail:'晚点 8 分钟',plan:'计划 14:00',progress:null})}${section('这一段',`<div class="card">${row('<span class="train-mark">VIA 44</span>','<span class="small muted">11月6日</span>')}<div class="route-title" style="margin:16px 0">Toronto ${I('arrow.right')} Ottawa</div>${row('<span class="small muted">预计到达</span>','<b class="mono">18:38</b>')}</div>`)}${notice('预计时间可能变化，请留意车站广播和登车安排。','warning','bell')}<div class="spacer"></div>${button('我已上车','primary','checkmark','detail')}<div class="tiny muted" style="text-align:center">13:55 更新 · 列车尚未确认发车</div>`,{title:'行程详情',back:'行程',time:'13:55'}),'12 · 候车中');
