function sidebar(stage='行进中',updated='17:24'){return `<aside class="ipad-sidebar"><h1>VIA Tracker</h1><div><div class="side-option selected">${I('house.fill')}我的行程</div><div class="side-option">${I('tram.fill')}列车列表</div></div><div class="row side-caption"><span>已保存的行程</span>${I('plus','sm')}</div><div class="sidebar-trip selected"><span class="tiny accent">当前主行程 · ${stage}</span><h3>Toronto → Montréal</h3><div class="small muted">今天 · 经 Ottawa 换乘</div><div class="small" style="margin-top:14px">${I('tram.fill','sm')} VIA 44 + VIA 38</div></div><div class="sidebar-trip"><span class="tiny muted">11月8日 · 待同步</span><h3>Montréal → Toronto</h3><div class="small muted">VIA 61 · 06:45 参考时刻</div></div><div class="spacer"></div><div class="side-option">${I('gearshape')}设置</div><div class="side-caption" style="line-height:1.8">最近更新 ${updated}<br>行程已保存在本机</div></aside>`}
function ipadDetail(id,dark=false,narrow=false){return{id,type:'tablet',width:narrow?700:1194,height:narrow?940:834,html:`<article id="art-${id}" class="art tablet ${dark?'dark':''} ${narrow?'narrow-tablet':''}">${status('17:24',true)}<div class="ipad-layout">${sidebar()}<div class="ipad-main"><div class="ipad-title"><div><div class="tiny muted" style="margin-bottom:5px">11月6日 周五 · 2 段列车</div><h2>Toronto → Montréal</h2></div><div class="ipad-toolbar">${pill('实时','','antenna.radiowaves.left.and.right')}<span style="color:var(--accent)">${I('ellipsis')}</span></div></div><div class="ipad-columns"><div class="ipad-column">${hero()}${mapArt(true)}${narrow?'<div class="card compact">'+row('<div class="col"><span class="tiny muted">下一站</span><h3>Smiths Falls</h3></div>','<div class="col" style="align-items:flex-end"><span class="mono">17:38</span><span class="tiny muted">预计到达</span></div>')+'</div>'+nextSegment(true):'<div class="tiny muted">位置上报 17:23 · 时刻获取 17:24 · 进度按时刻推算</div>'}<div class="spacer"></div><div class="row"><span class="small muted">实时活动进行中</span><button class="edit-link" data-jump="edit">管理追踪 ${I('chevron.right','sm')}</button></div></div><div class="ipad-column"><div class="card"><div class="section-label"><span>当前段 · VIA 44</span><span class="muted">计划 / 预计</span></div>${timeline()}<div class="divider" style="margin:12px 0 17px"></div><div class="transfer-strip"><span>到达后，距下一段计划发车</span><b>33 分钟</b></div></div>${nextSegment()}<div class="card compact">${row('<div class="col"><span class="small muted">最终目的站</span><h3>Montréal</h3></div>','<div class="col" style="align-items:flex-end"><span class="mono final-time">21:12</span><span class="tiny muted">预计到达</span></div>')}</div></div></div></div></div>${footer()}</article>`}}
add(ipadDetail('ipad-detail'),'37 · iPad 横屏 · 行程详情');add(ipadDetail('ipad-dark',true),'38 · iPad 横屏 · 深色');add(ipadDetail('ipad-narrow',false,true),'39 · iPad 窄窗口 · 单列');

/* Lock Screen Live Activities */
function live({stage='行进中',label='距 Ottawa 预计到达',count='1小时18分',num='44',right='18:42',rightLabel='预计到达',detail='晚点 12 分钟 · 计划 18:30',foot='下一段 VIA 38 · 19:15',rightFoot='间隔 33 分钟',progress=true,stale=false}={}){return `<div class="live-card"><div class="live-head"><span class="train-mark">${I('tram.fill','sm')}VIA ${num}</span><span class="${stale?'muted':'accent'}">${stage}</span></div><div class="live-body"><div><div class="status-label">${label}</div><div class="live-number">${count}</div></div><div style="text-align:right"><div class="small muted">${rightLabel}</div><div class="mono" style="font-size:23px;line-height:1.2;margin-top:5px">${right}</div></div></div>${progress?'<div class="progress-track"><div class="progress-fill" style="width:72%"></div></div>':'<div style="height:12px"></div>'}<div class="tiny ${detail.includes('晚点')?'amber':'muted'}">${detail}</div><div class="live-footer"><span>${foot}</span><span>${rightFoot}</span></div></div>`}
