function surface(id,title,sub,body,extra='',height=834){return{id,type:'surface',width:1194,height,html:`<article id="art-${id}" class="art surface-board ${extra}" style="height:${height}px"><h2>${title}</h2><div class="surface-sub">${sub}</div>${body}<div class="demo-tag">演示数据 · 静态设计稿</div></article>`}}
add(surface('live-states','实时活动 · 全部状态','一个行程，一张持续更新的卡片。当前车段变化，关注重点随之切换。',`<div class="surface-grid">${liveStates.map(([label,args])=>`<div class="surface-cell"><div class="surface-label">${label}</div>${live(args)}</div>`).join('')}</div>`,'',1260),'41 · 实时活动 · 八种状态');
function lock(id,dark=false){return{id,type:'phone',width:402,height:874,html:`<article id="art-${id}" class="art phone lock-screen ${dark?'dark':''}">${status('17:24')}<div class="lock-date">11月6日 星期五</div><div class="lock-clock">17:24</div><div class="screen-body">${live()}<div class="spacer"></div></div><div class="lock-bottom"><div class="lock-circle">${I('bolt.fill')}</div><div class="lock-circle">${I('circle')}</div></div>${footer()}</article>`}}
