const islandExpanded=(transfer=false)=>`<div class="island-expanded"><div class="row" style="margin-bottom:25px"><span class="train-mark">${I(transfer?'arrow.triangle.branch':'tram.fill','sm')}VIA ${transfer?'38':'44'}</span><span class="small accent">${transfer?'换乘中':'行进中'}</span></div><div class="row" style="align-items:flex-end"><div><div class="small muted">${transfer?'距下一段计划发车':'距 Ottawa 预计到达'}</div><div class="live-number mono">${transfer?'33:00':'1:18:00'}</div></div><div style="text-align:right"><div class="small muted">${transfer?'计划发车':'预计到达'}</div><div class="mono" style="font-size:25px">${transfer?'19:15':'18:42'}</div></div></div><div class="progress-track"><div class="progress-fill" style="width:${transfer?0:72}%"></div></div><div class="row small"><span>${transfer?'Ottawa → Montréal':'下一段 VIA 38 · 19:15'}</span><span class="accent">${transfer?'同站换乘':'间隔 33 分钟'}</span></div></div>`;
add(surface('islands','灵动岛 · 三种形态','紧凑、最小与展开形态。显示当前阶段、剩余时间与下一段。',`<div class="island-row-label">行进中 · 17:24</div><div class="island-demo-area"><div><div class="surface-label">紧凑</div><div class="island-pill">${I('tram.fill')}<span class="mono">1小时18分</span></div></div><div><div class="surface-label">最小</div><div class="island-minimal">${I('tram.fill')}</div></div><div><div class="surface-label">展开</div>${islandExpanded()}</div></div><div class="island-row-label">换乘中 · 18:42</div><div class="island-demo-area"><div><div class="surface-label">紧凑</div><div class="island-pill">${I('arrow.triangle.branch')}<span class="mono">33 分钟</span></div></div><div><div class="surface-label">最小</div><div class="island-minimal">${I('arrow.triangle.branch')}</div></div><div><div class="surface-label">展开</div>${islandExpanded(true)}</div></div><div class="token-caption" style="margin-top:35px">倒计时归零后等待数据确认；不因时间经过而宣布列车发车或到达。所有数字为冻结的演示快照。</div>`,'island-board',850),'45 · 灵动岛 · 完整形态');
function widget(small=false,dark=false,offline=false){return `<div class="art widget ${small?'small-widget':'medium-widget'} ${dark?'dark':''}">${row(`<span class="train-mark">${I('tram.fill','sm')}VIA ${small?'44':'44 + 38'}</span>`,`<span class="tiny ${offline?'muted':'accent'}">${offline?'数据较旧':'行进中'}</span>`)}${small?`<div><div class="tiny muted">距 Ottawa 预计到达</div><div class="widget-count" style="margin-top:7px">1小时18分</div></div><div class="widget-foot">${offline?'最近数据 17:12':'17:24 更新 · 预计 18:42'}</div>`:`<div class="widget-cols"><div class="col"><div class="tiny muted">距 Ottawa 预计到达</div><div class="widget-count" style="margin-top:6px">1小时18分</div></div><div class="widget-divider"></div><div class="col" style="gap:4px"><span class="tiny muted">下一段 · VIA 38</span><span class="widget-title">19:15 → Montréal</span><span class="tiny accent">到达后间隔 33 分钟</span></div></div><div class="widget-foot">${offline?'最近数据 17:12 · 时间可能已变化':'17:24 更新 · 进度按时刻推算'}</div>`}</div>`}
add(surface('widgets','主屏幕小组件','小号聚焦下一站，中号补充换乘。更新遵循系统调度，始终标注数据时间。',`<div class="island-row-label">浅色 · 当前行程</div><div class="widget-area"><div><div class="surface-label">小号</div>${widget(true)}</div><div><div class="surface-label">中号</div>${widget()}</div></div><div class="island-row-label">深色与过期数据</div><div class="widget-area"><div><div class="surface-label">深色 · 小号</div>${widget(true,true)}</div><div><div class="surface-label">数据较旧 · 中号</div>${widget(false,false,true)}</div></div><div class="token-caption">小组件轻点进入对应行程。它不承担实时活动的持续更新职责，离线仍保留最近有效信息。</div>`,'',850),'46 · 小组件 · 大小与状态');

/* Visual specification board */
add(surface('foundation','视觉规范','系统字体 · SF Symbols · 暖白与 VIA 黄色 · 基于 iOS / iPadOS 18 的原生结构',`<div class="design-tokens"><div class="token-col"><div><div class="surface-label">01 / 颜色</div><div class="swatches">${['#f6f5f0','#fffefa','#252622','#FFCC00','#94601a'].map(c=>`<div class="swatch" style="background:${c}"></div>`).join('')}</div><div class="token-caption" style="margin-top:14px">画布 #F6F5F0 · 表面 #FFFEFA · 文字 #252622<br>主色 #FFCC00 · 延误 #94601A（辅以明确文字）</div></div><div class="type-sample"><div class="surface-label">02 / 数字与层级</div><div class="sample-number mono">1:18:00</div><div style="font-size:30px;letter-spacing:-1px;margin:12px 0">前往 Ottawa</div><div style="font-size:15px">下一站 Smiths Falls · 预计 17:38</div><div class="token-caption" style="margin-top:8px">SF Pro / PingFang SC · 等宽数字 · 正文 15–17pt</div></div><div><div class="surface-label">03 / 触达与留白</div><div class="component-row">${button('主要操作')}${button('次要操作','outline')}</div><div class="token-caption" style="margin-top:12px">主要按钮 50pt · 图标触达 44pt · 页面边距 24pt<br>卡片圆角 22–24pt · 相邻信息间距 16–24pt</div></div></div><div class="token-col"><div><div class="surface-label">04 / 符号与状态</div><div class="component-row">${['tram.fill','figure.walk','arrow.triangle.branch','clock','wifi.slash','location.fill','bell','checkmark.circle.fill'].map(n=>I(n)).join('')}</div><div class="component-row" style="margin-top:25px">${pill('行进中')}${pill('晚点 12 分钟','amber')}${pill('数据过期','neutral')}</div></div><div><div class="surface-label">05 / 不混淆时间的含义</div><div class="list-group">${listRow('官方计划','18:30','clock')}${listRow('官方预计','18:42','tram.fill')}${listRow('规划发车','14:00','house')}</div><div class="token-caption" style="margin-top:12px">计划是基准，预计会变化；用户规划仅用于出门推算。<br>个人状态与列车运行状态分别呈现。</div></div><div><div class="surface-label">06 / 可访问性与适配</div><div class="token-caption">动态字体放大时让信息重排，保留主操作；<br>倒计时提供完整朗读标签，状态变化再播报；<br>不依赖颜色、动效或悬停传达关键意义；<br>地图始终有站点时间轴作为替代。</div></div><div class="notice neutral">${I('info.circle')}<div>地图为绘制的位置示意，并非 Apple 地图截图。正式产品使用 MapKit，不推测缺失的铁路轨迹。</div></div></div></div>`,'',940),'47 · 视觉规范与交接');

add(surface('architecture','技术架构与刷新策略','技术交接 / 原生 iOS 与 iPadOS 18+ / 本稿集不运行服务或请求实时数据',`<div class="architecture-flow"><div class="card tint"><h3>SwiftUI App</h3><div class="small muted">行程 / SwiftData 本地快照<br>MapKit / App Group</div></div>${I('arrow.right')}<div class="card tint"><h3>Cloudflare Workers</h3><div class="small muted">统一抓取 VIA / 数据规范化<br>D1 快照与订阅 / 每分钟调度</div></div>${I('arrow.right')}<div class="card tint"><h3>APNs → ActivityKit</h3><div class="small muted">合并变化 / 推送活动状态<br>WidgetKit 共用本机快照</div></div></div><div class="handoff-grid"><div class="handoff-item"><h3>01 / 行程与班次身份</h3><p>Journey 包含有序 TrainLeg；相同车站代码关联同站接续。<br>班次以车次号 + 始发日期定位；上车站当地日期与始发日期分开保存。<br>日期、时区、站序和跨日偏移保留原始含义，不仅靠 JSON 的显示键匹配。</p></div><div class="handoff-item"><h3>02 / 互不覆盖的三套时刻</h3><p>scheduled / estimated / planningDeparture 分别保存。<br>planningDeparture 只改变出门前推算；上车后始终使用对应站官方信息。<br>未来日期只复制计划，首次匹配若不同则通知一次；同步选择仅对本行程有效。</p></div><div class="handoff-item"><h3>03 / 刷新与推送节奏</h3><p>Worker 每分钟统一抓取；相同数据不重复广播。<br>阶段变化和关键时刻变化触发推送，预计时间变化至少一分钟才合并更新。<br>常规 APNs 优先级 5，重要变化才用 10；系统预算和送达不作保证。</p></div><div class="handoff-item"><h3>04 / 真正区分离线与陈旧</h3><p>快照分别保存 fetchedAt / positionReportedAt / validUntil。<br>联网成功但列车未重新定位，不能改写定位年龄。<br>前台恢复连接即刷新，失败按5/15/30/60秒退避并加抖动；后台遵循系统调度。</p></div><div class="handoff-item"><h3>05 / 最小服务接口</h3><p><code>GET /trains　GET /trains/:instanceId</code><br><code>POST /subscriptions　PATCH /subscriptions/:id</code><br><code>DELETE /subscriptions/:id</code><br>订阅含行程段、活动令牌与更新偏好；服务器凭证只存服务端，设备订阅需认证。</p></div><div class="handoff-item"><h3>06 / 系统生命周期与实现验证</h3><p>客户端按时间戳绘制倒计时，不为每秒变化推送。staleDate 到期显示过期。<br>单次活动8小时后，用户打开 App 再续开；不自动重置时限。<br>真机验证 APNs、活动权限、Dynamic Type、VoiceOver、时区与离线恢复。</p></div></div><div class="notice neutral" style="margin-top:30px">${I('info.circle')}<div>先使用演示数据实现原生界面，再接入数据规范化与APNs。换乘只展示时间差；不提供自动改签、自动接续推荐或误车判断。</div></div>`,'',940),'48 · 架构与刷新逻辑');

const groups=[
{id:'journey',name:'行程详情',en:'THE JOURNEY',title:'行程详情',description:'显示当前阶段、剩余时间和逐站时刻，覆盖单程、同站换乘与深色模式。',ids:['detail','connection','detail-dark'],note:'统一演示快照：2026年11月6日 17:24（America/Toronto）。VIA 44：Toronto 14:00 → Ottawa 计划18:30 / 预计18:42；VIA 38：Ottawa 19:15 → Montréal 21:12。两段间隔33分钟。车次与时刻用于设计演示，不代表真实运营安排。'},
{id:'homes',name:'我的行程',en:'YOUR TRIPS',title:'我的行程',description:'可保存多趟行程；默认突出最近的未完成行程，当前追踪保持唯一。',ids:['empty','upcoming','home']},
{id:'select',name:'添加 · 车次与区间',en:'CREATE / 01',title:'选择列车与乘车区间',description:'实时班次和未来日期分开表达。日期缺少数据时借用参考计划，不冒用其他日期的运行状态。',ids:['search','date','stations','boarding-picker','alighting-picker']},
{id:'planning',name:'添加 · 时间与耗时',en:'CREATE / 02',title:'规划时间与前往耗时',description:'用户设置规划发车时间及前往耗时，计算计划出门时间。不额外添加候车余量。',ids:['departure','travel','review']},
{id:'transfers',name:'添加 · 换乘',en:'CREATE / CONNECTION',title:'添加同站换乘',description:'仅支持同站接续，换乘间隔由两段列车的到发时间计算，无需设置换乘耗时。',ids:['add-transfer','transfer-unavailable','transfer-review'],note:'换乘仅匹配车站代码相同的上一段下车站和下一段上车站。不提供异站换乘、站间交通或换乘耗时设置。'},
{id:'phases',name:'出发前 · 前往 · 候车',en:'BEFORE BOARDING',title:'出发前、前往与候车',description:'出发前看到出门倒计时；前往中以计划发车为基准；候车时切换到官方预计发车。允许个人状态手动纠正。',ids:['before','onway','waiting']},
{id:'connection-phases',name:'换乘 · 下一段 · 抵达',en:'THE NEXT LEG',title:'换乘与抵达',description:'实时活动随当前车段切换。换乘时突出下一段计划发车，最终段回到目的站到达倒计时。',ids:['interchange','second-leg','complete']},
{id:'syncing',name:'参考时刻与同步',en:'SCHEDULE / SYNC',title:'参考时刻与官方同步',description:'未来班次首次匹配后，如与规划值不同，仅提醒一次并让用户决定当前行程是否自动同步。已有正式班次的手动调整先提示。',ids:['reference','manual-warning','sync','notification']},
{id:'network',name:'离线与数据质量',en:'OFFLINE / DATA AGE',title:'离线与数据状态',description:'设备断网、服务失败和定位陈旧分别表达。倒计时按最后有效数据继续，获取时间不会掩盖源数据的年龄。',ids:['offline','server-error','stale-position','recovered']},
{id:'lifecycle',name:'等待更新与活动续开',en:'ACTIVITY / LIFECYCLE',title:'等待更新与续开',description:'预计时刻已过时等待更新；实时活动到期后由用户续开；系统不允许活动时，行程仍可在App内查看。',ids:['pending-update','expired','activity-off']},
{id:'edges',name:'跨日 · 时区 · 中途上车',en:'ROUTE / EDGE CASES',title:'特殊行程',description:'中途站使用本站到发信息，跨日补上日期，跨时区保留当地时区；缺少定位时回到路线示意。',ids:['midboard','crossday','timezone','no-position']},
{id:'manage',name:'设置与行程管理',en:'PREFERENCES',title:'设置与行程管理',description:'管理出门规划、乘车区间、换乘与个人阶段。结束追踪需要确认，保存的行程仍保留在本机。',ids:['settings','edit','correct-stage','end-confirm']},
{id:'accessibility',name:'小屏与大字体',en:'ACCESSIBILITY',title:'小屏与大字体',description:'320pt小屏保留完整时刻和主要信息；大字体优先显示当前目的地、倒计时和下一站，次要信息下沉。',ids:['small-device','large-text'],note:'这是静态可访问性布局稿，不代表已完成原生Dynamic Type或VoiceOver验证。正式实现需补充系统字号、朗读顺序、状态播报与真机测试。'},
{id:'ipad',name:'iPad · 横屏与窗口',en:'DESIGNED FOR iPAD',title:'iPad 布局',description:'侧栏管理行程，左侧看倒计时与位置，右侧看逐站时间和接续。窄窗口收为单列。',ids:['ipad-detail','ipad-dark','ipad-create','ipad-narrow']},
{id:'lock',name:'锁屏 · iPhone 与 iPad',en:'LIVE AT A GLANCE',title:'锁屏实时活动',description:'锁屏呈现最重要的当前状态与接续信息。iPad使用独立锁屏排布，不把灵动岛搬到iPad。',ids:['lock-light','lock-dark','ipad-lock']},
{id:'live',name:'实时活动 · 全部状态',en:'LIVE ACTIVITIES',title:'实时活动状态',description:'八个关键状态覆盖准备、乘车、换乘、数据过期和结束。过期不声称断网，最后已知时间也不冒充实时。',ids:['live-states'],note:'此页展示静态系统组件稿。实际ActivityKit的布局、更新预算与可交互区域需要真机验证；8小时后不能继续更新原活动，须由用户重新开启。'},
{id:'island',name:'灵动岛 · 三种形态',en:'DYNAMIC ISLAND',title:'灵动岛形态',description:'紧凑形态保留阶段符号和剩余时间；展开形态补充时刻、目的站和下一段。',ids:['islands']},
{id:'widget',name:'小组件',en:'HOME SCREEN WIDGETS',title:'主屏幕小组件',description:'小号聚焦当前段，中号补充下一段。始终保留更新时间，数据较旧时明确标注。',ids:['widgets']},
{id:'spec',name:'视觉规范与实现说明',en:'DESIGN / HANDOFF',title:'视觉规范与实现说明',description:'视觉规则、状态语义与技术交接。稿件全部自包含，离线打开即可浏览，不连接VIA或地图服务。',ids:['foundation','architecture'],note:'实现建议：SwiftUI + ActivityKit + WidgetKit + MapKit + SwiftData/App Group；Cloudflare Workers统一抓取、D1保存快照与订阅，APNs按变化合并推送。未来日期匹配以车次号和始发日期为键；车站当地日期独立处理跨日和时区。服务器每分钟抓取，前台重试5/15/30/60秒；后台不承诺持续执行。所有用户可见的时刻都携带来源、获取时间和定位上报时间。'}
];

/*__STATION_SELECTION__*/

let currentGroup='journey';
function targetScale(screen,available){if(screen.type==='phone')return Math.min(1,available/screen.width);return Math.min(1,available/screen.width)}
function renderGroup(id,scroll=true){const group=groups.find(g=>g.id===id)||groups[0];currentGroup=group.id;document.getElementById('eyebrow').textContent=group.en;document.getElementById('section-title').textContent=group.title;document.getElementById('section-description').textContent=group.description;document.getElementById('page-count').textContent=`${String(groups.indexOf(group)+1).padStart(2,'0')} / ${groups.length}　·　${group.ids.length} 张稿件`;document.getElementById('board-note').textContent=group.note||'';document.querySelectorAll('.catalog button').forEach(el=>{el.classList.toggle('active',el.dataset.group===group.id);if(el.dataset.group===group.id)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});document.getElementById('artboards').innerHTML=group.ids.map(id=>{const s=screens[id];return `<div class="art-wrap" data-screen="${id}"><div class="device-space" data-w="${s.width}" data-h="${s.height}" data-type="${s.type}">${s.html}</div><div class="art-label"><b>${s.label}</b><span>${s.width} × ${s.height}</span></div></div>`}).join('');resizeArtboards();if(scroll)window.scrollTo({top:0,behavior:'instant'});history.replaceState(null,'',`#${group.id}`)}
function resizeArtboards(){const area=document.getElementById('artboards');if(!area)return;const aw=area.clientWidth;document.querySelectorAll('.device-space').forEach(el=>{const w=Number(el.dataset.w),h=Number(el.dataset.h);let max=aw;if(el.dataset.type==='phone'){const cols=aw>=1160?3:aw>=750?2:1;max=Math.min(402,(aw-32*(cols-1))/cols)}const scale=Math.min(1,max/w);el.style.width=`${w*scale}px`;el.style.height=`${h*scale}px`;el.firstElementChild.style.transform=`scale(${scale})`;el.parentElement.style.width=`${w*scale}px`})}
document.getElementById('brand-icon').innerHTML=I('tram.fill');
document.getElementById('catalog').innerHTML='<div class="catalog-title">DESIGN INDEX / 稿件目录</div>'+groups.map((g,n)=>`<button data-group="${g.id}"><em>${String(n+1).padStart(2,'0')}</em><span>${g.name}</span></button>`).join('')+`<div class="catalog-foot">${Object.keys(screens).length} 张完整稿件<br>${groups.length} 组场景与界面<br>中文 · 浅色 / 深色<br><br>本文件为静态设计稿集。<br>目录与流程按钮用于翻页，<br>数据不会实时更新。</div>`;
document.addEventListener('click',e=>{const g=e.target.closest('[data-group]');if(g){renderGroup(g.dataset.group);return}const jump=e.target.closest('[data-jump]');if(jump){const group=groups.find(g=>g.ids.includes(jump.dataset.jump));if(group){renderGroup(group.id);requestAnimationFrame(()=>document.querySelector(`[data-screen="${jump.dataset.jump}"]`)?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}))}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]')){e.preventDefault();e.target.click()}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(resizeArtboards,80)});
window.VIA_DESIGN={screens,groups,renderGroup};
renderGroup(location.hash.slice(1)||'journey',false);
